,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select count(*) as submitted,',
'       sum(case when quality_status = ''Accepted'' then 1 else 0 end) as accepted,',
'       sum(case when quality_status = ''Review''   then 1 else 0 end) as review,',
'       sum(case when quality_status = ''Rejected'' then 1 else 0 end) as rejected,',
'       round(avg(case when quality_status = ''Accepted'' then systolic end))         as avg_systolic,',
'       round(avg(case when quality_status = ''Accepted'' then diastolic end))        as avg_diastolic,',
'       round(avg(case when quality_status = ''Accepted'' then pulse_rate end))       as avg_pulse,',
'       round(avg(case when quality_status = ''Accepted'' then spo2 end))             as avg_spo2,',
'       round(avg(case when quality_status = ''Accepted'' then body_weight_kg end), 1) as avg_weight_kg',
'  from readings',
' where patient_id = :P8_PATIENT_ID',
'   and measured_at >= localtimestamp - interval ''30'' day'))
